			// Ignore links with .rzBtn children
			if ($(this).find('span.rzBtn').length === 0) {
				const linkUrl = $(this).prop('href');
				const linkHost = new URL(linkUrl).hostname;
				const currentHost = window.location.hostname;

				// Treat current domain and all revize.com domains/subdomains as internal
				const isRevizeDomain =
					linkHost === 'revize.com' ||
					linkHost.endsWith('.revize.com');

				// If different domain and NOT a Revize domain, show confirmation popup
				if (linkHost !== currentHost && !isRevizeDomain) {
					event.preventDefault();
					externalLink = linkUrl;
					$('.confirmation-popup').addClass('show').show();
				}
			}
		});

	// Confirm external navigation
	$('#confirmLeave').on('click', function () {
		if (externalLink) {
			window.open(externalLink, '_blank');
		}

		$('.confirmation-popup').removeClass('show').hide();
		externalLink = '';
	});

	// Cancel external navigation
	$('#cancelLeave').on('click', function () {
		$('.confirmation-popup').removeClass('show').hide();
		externalLink = '';
