	rid = String(rid);
	var cRecord = bidJSONData[rid];
	if (!cRecord) return false;

	var m = bidDetailsMap;
	var parsedOptions = cRecord.options || {};

	if (m.titleB) m.titleB.textContent = cRecord.title || "";

	// STATUS
	if (m.statusEl) {
		var status = (parsedOptions.val_status || "").trim();
		if (status) {
			m.statusEl.className = "small px-2 py-1 rounded-1 bid-status " + statusClass(status);
			m.statusEl.textContent = status;
			m.statusEl.classList.remove("d-none");
		} else {
			m.statusEl.classList.add("d-none");
			m.statusEl.textContent = "";
		}
	}

	// DATES (Start/End)
	var sd = fmtDate(parsedOptions.start_date || parsedOptions.startDate);
	var ed = fmtDate(parsedOptions.end_date   || parsedOptions.endDate);
	
	if (m.startWrap && m.startEl) {
		if (sd) {
			m.startEl.textContent = sd;
			m.startWrap.classList.remove("d-none");
		} else {
			m.startEl.textContent = "";
			m.startWrap.classList.add("d-none");
		}
	}
	
	if (m.endWrap && m.endEl) {
		if (ed) {
			m.endEl.textContent = ed;
			m.endWrap.classList.remove("d-none");
		} else {
			m.endEl.textContent = "";
			m.endWrap.classList.add("d-none");
		}
	}

	if (m.apply) {
		var btnURL  = (parsedOptions.website_url || "").trim();
		var btnText = (parsedOptions.website_text || "Learn More").trim();

		if (btnURL && btnURL !== "#") {
			m.apply.classList.remove("d-none");
			m.apply.setAttribute("href", btnURL);
			m.apply.setAttribute("target", "_blank");
			m.apply.innerHTML = btnText + '<i class="bi bi-box-arrow-up-right ms-2"></i>';
		} else {
			m.apply.classList.add("d-none");
			m.apply.setAttribute("href", "#");
		}
	}

	if (m.detail) {
		var pane = m.detail;
		pane.innerHTML = "Loading...";

		fetch('bids/' + encodeURIComponent(rid) + '.php?display=json')
			.then(function(res){ return res.json(); })
			.then(function(data){
				var html = (data && data.details) ? String(data.details).trim() : "";
				pane.innerHTML = html || "";
			})
			.catch(function(){
				pane.innerHTML = "";
			});
	}

	try {
		bootstrap.Offcanvas.getOrCreateInstance(m.modal).show();
	} catch(e) {
		console.error('Offcanvas show failed:', e);
	}

	if (window.pushOcState) pushOcState('bidDetails', rid);

	return false;
}

document.addEventListener('DOMContentLoaded', function() {
	var modal = document.querySelector("#bidDetails");
	if (!modal) return;

	bidDetailsMap = {
		modal: modal,
		titleB: modal.querySelector(".bid-title"),
		statusEl: modal.querySelector(".bid-status"),
		startWrap: modal.querySelector(".bid-start-wrap"),
		endWrap: modal.querySelector(".bid-end-wrap"),
		startEl: modal.querySelector(".bid-start-date"),
		endEl: modal.querySelector(".bid-end-date"),
		detail: modal.querySelector(".bid-full-details"),
		apply: modal.querySelector(".apply-link")
	};

	fetch('_includes_/published/bids_list.json')
		.then(function(res){ return res.json(); })
		.then(function(data){ bidJSONData = indexByIdOrRid(data); })
		.then(function(){ if (typeof tryDeepLinkNow === 'function') tryDeepLinkNow('bidDetails'); })
		.catch(function(e){
			console.error('bids_list.json load failed', e);
			bidJSONData = {};
		});
});
 
	 
		 
			 
				 
